function formatLines(n) {
  return n.toLocaleString("en-US");
}

function namedCommitSum() {
  var sum = 0;
  for (var i = 0; i < PARTS.length; i++) {
    if (PARTS[i].commits != null) sum += PARTS[i].commits;
  }
  return sum;
}

var NAMED_COMMIT_SUM = namedCommitSum();

function colorFor(index, isRest) {
  return isRest ? "mute" : COLORS[index % COLORS.length];
}

function makeSeg(part, index, kind) {
  var btn = document.createElement("button");
  btn.type = "button";
  btn.className = "seg " + colorFor(index, part.id === "rest");
  btn.setAttribute("role", "listitem");
  btn.dataset.id = part.id;
  btn.setAttribute("aria-pressed", selectedId === part.id ? "true" : "false");

  var widthPct;
  var numText;
  var labelExtra = "";

  if (kind === "size") {
    widthPct = part.share;
    numText = part.share.toFixed(1) + "% · " + formatLines(part.lines) + " lines";
    btn.title = part.role + " — " + numText;
    if (part.share < 5 && part.id !== "rest") {
      btn.className += " compact";
    }
