    if (part.id === "rest") {
      widthPct = 18;
      numText = "36 files · spread in history";
      btn.title = "Everything else — commit counts vary; not summed (would double-count)";
    } else {
      widthPct = (part.commits / NAMED_COMMIT_SUM) * 82;
      numText = part.commits + (part.commits === 1 ? " commit" : " commits");
      btn.title = part.role + " — " + numText + " in history available";
      if (part.commits <= 3) btn.className += " compact";
    }
  }

  btn.style.flex = "0 0 " + widthPct + "%";
  btn.style.width = widthPct + "%";

  var inner = document.createElement("span");
  inner.className = "inner";
  var name = document.createElement("span");
  name.className = "name";
  name.textContent = part.role;
  var num = document.createElement("span");
  num.className = "num";
  num.textContent = numText;
  inner.appendChild(name);
  inner.appendChild(num);
  btn.appendChild(inner);

  btn.addEventListener("click", function () {
    selectPart(part.id, true);
  });

  return btn;
}

